_CORE_SRC = '# Diagnosis:\n# The close c3 pairing (including a seat-1 loss) does not prove a particular\n# map weakness. The code does expose a forecast weakness: it forecasts once,\n# against routes that it subsequently changes, and blends immobile enemy\n# capacity into every future turn. Fast best responders therefore contest\n# different nodes from those assumed by the route search.\n#\n# Keep the champion\'s stock-aware multistop search and exact margin objective.\n# Change two things: calibrate the enemy forecast from observed prediction\n# errors, and refresh that forecast between coordinate-descent sweeps.\n# A smaller, diversity-preserving beam permits more complete fleet sweeps.\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nCAP = {"truck": 8, "scooter": 3}\nCOST = {"truck": 3.0, "scooter": 1.5}\nSPEED = {"truck": 1, "scooter": 2}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.key = None\n        self.dist = []\n        self.reach = {}\n        self.plans = {}\n        self.last_turn = None\n        self.last_enemy = {}\n        self.predicted = {}\n        self.trust = 0.65\n        self.bad = 0\n\n    def prepare(self, obs):\n        n = obs["n_nodes"]\n        key = (n, tuple(tuple(e) for e in obs["edges"]))\n        if key == self.key:\n            return\n        adj = [[] for _ in range(n)]\n        for a, b in obs["edges"]:\n            adj[a].append(b)\n            adj[b].append(a)\n        self.dist = []\n        for s in range(n):\n            d = [n + 1] * n\n            d[s] = 0\n            q = deque([s])\n            while q:\n                u = q.popleft()\n                for v in sorted(adj[u]):\n                    if d[v] > d[u] + 1:\n                        d[v] = d[u] + 1\n                        q.append(v)\n            self.dist.append(d)\n        self.reach = {\n            sp: [[v for v in range(n) if self.dist[u][v] <= sp]\n                 for u in range(n)] for sp in (1, 2)\n        }\n        self.key = key\n        self.plans = {}\n\n    def home_route(self, source, speed, home, horizon):\n        route = []\n        for _ in range(horizon):\n            source = min(self.reach[speed][source],\n                         key=lambda v: (self.dist[v][home], v))\n            route.append(source)\n        return route\n\n    @staticmethod\n    def margin(a, b, s):\n        den = max(a + b, s)\n        return (a - b) * s / den if den else 0.0\n\n    def predict(self, obs, plans, horizon):\n        n = obs["n_nodes"]\n        enemy = obs["opponent_units"]\n        base = obs["opponent_base"]\n        stock = list(obs["stock"])\n        pos = {u: data[1] for u, data in enemy.items()}\n        fixed = [0.0] * n\n        for typ, node in enemy.values():\n            fixed[node] += CAP[typ]\n        inactive = (obs["turn"] >= 2 and\n                    all(data[1] == base for data in enemy.values()) and\n                    abs(obs.get("opponent_cumulative_profit", 0.0)) < 0.01)\n        forecasts = []\n        first = {}\n        order = sorted(enemy, key=lambda u: (-CAP[enemy[u][0]], u))\n        for h in range(horizon):\n            ours = [0.0] * n\n            for uid, (typ, _) in obs["player_units"].items():\n                ours[plans[uid][h]] += CAP[typ]\n            allocated = [0.0] * n\n            # Two coordinate passes avoid permanently privileging early ids.\n            targets = dict(pos)\n            for uid, (typ, _) in enemy.items():\n                allocated[targets[uid]] += CAP[typ]\n            for sweep in range(2):\n                for uid in (order if sweep == 0 else reversed(order)):\n                    typ = enemy[uid][0]\n                    cap, cost, speed = CAP[typ], COST[typ], SPEED[typ]\n                    allocated[targets[uid]] -= cap\n                    source = pos[uid]\n                    best, value = source, -1e100\n                    for v in self.reach[speed][source]:\n                        gain = (self.margin(allocated[v] + cap, ours[v], stock[v])\n                                - self.margin(allocated[v], ours[v], stock[v]))\n                        if v != base:\n                            gain -= cost\n                            gain -= 0.20 * cost * (\n                                (self.dist[v][base] + speed - 1) // speed)\n                        if v == source:\n                            gain += 0.025\n                        if gain > value + 1e-10:\n                            best, value = v, gain\n                    targets[uid] = best\n                    allocated[best] += cap\n            pos = targets\n            if h == 0:\n                first = dict(pos)\n            # Uncertainty about current moves should not freeze a ghost fleet\n            # on its old nodes throughout the entire planning horizon.\n            weight = 1.0 - (1.0 - self.trust) * (0.64 ** h)\n            if inactive:\n                weight = 0.015\n            row = [weight * allocated[v] + (1.0 - weight) * fixed[v]\n                   for v in range(n)]\n            forecasts.append(row)\n            for v in range(n):\n                stock[v] = round(min(obs["stock_max"][v],\n                                     max(0.0, stock[v] - row[v] - ours[v])\n                                     + obs["regen"][v]), 2)\n        return forecasts, first\n\n    def improve(self, uid, obs, plans, enemy, horizon, deadline):\n        n = obs["n_nodes"]\n        home = obs["player_base"]\n        typ, source = obs["player_units"][uid]\n        cap, cost, speed = CAP[typ], COST[typ], SPEED[typ]\n        other = [[0.0] * n for _ in range(horizon)]\n        for u, (t, _) in obs["player_units"].items():\n            if u != uid:\n                for h, v in enumerate(plans[u]):\n                    other[h][v] += CAP[t]\n        maxima, regen = obs["stock_max"], obs["regen"]\n        discounts = [0.96 ** h for h in range(horizon)]\n        terminal_weight = 0.65 * (0.96 ** horizon)\n        if obs["turn"] + horizon >= 60:\n            terminal_weight = 0.0\n        liability = [terminal_weight * cost *\n                     ((self.dist[v][home] + speed - 1) // speed)\n                     for v in range(n)]\n        margin = self.margin\n\n        def evaluate(path):\n            stock = list(obs["stock"])\n            score = 0.0\n            for h, node in enumerate(path):\n                value = -cost if node != home else 0.0\n                arow, brow = other[h], enemy[h]\n                for v in range(n):\n                    a = arow[v] + (cap if v == node else 0)\n                    b, s = brow[v], stock[v]\n                    value += margin(a, b, s)\n                    stock[v] = round(min(maxima[v],\n                                         max(0.0, s - a - b) + regen[v]), 2)\n                score += discounts[h] * value\n            return score - liability[path[-1]]\n\n        original = list(plans[uid])\n        best_path, best_value = original, evaluate(original)\n        beam = [(0.0, source, tuple(obs["stock"]), ())]\n        for h in range(horizon):\n            if time.perf_counter() >= deadline:\n                return best_path\n            children = []\n            arow, brow, disc = other[h], enemy[h], discounts[h]\n            for cumulative, position, stock, path in beam:\n                background = 0.0\n                nxt, local = [], []\n                for v in range(n):\n                    a, b, s = arow[v], brow[v], stock[v]\n                    m = margin(a, b, s)\n                    background += m\n                    local.append(m)\n                    nxt.append(round(min(maxima[v],\n                                         max(0.0, s - a - b) + regen[v]), 2))\n                for v in self.reach[speed][position]:\n                    a, b, s = arow[v], brow[v], stock[v]\n                    delta = margin(a + cap, b, s) - local[v]\n                    if v != home:\n                        delta -= cost\n                    score = cumulative + disc * (background + delta)\n                    ns = list(nxt)\n                    ns[v] = round(min(maxima[v],\n                                      max(0.0, s - a - b - cap) + regen[v]), 2)\n                    route = path + (v,)\n                    children.append((score - liability[v], score,\n                                     v, tuple(ns), route))\n            children.sort(key=lambda x: (-x[0], x[4]))\n            beam = []\n            counts = [0] * n\n            seen = set()\n            for _, score, v, stock, route in children:\n                state = (v, stock)\n                if counts[v] >= 2 or state in seen:\n                    continue\n                seen.add(state)\n                counts[v] += 1\n                beam.append((score, v, stock, route))\n                if len(beam) >= 16:\n                    break\n        for score, v, _, route in beam:\n            value = score - liability[v]\n            if value > best_value + 0.025:\n                best_path, best_value = list(route), value\n        return best_path\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        self.prepare(obs)\n        turn = int(obs["turn"])\n        units = obs["player_units"]\n        enemy_units = obs["opponent_units"]\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0)):\n            self.bad += 1\n        if self.last_turn == turn - 1 and self.predicted:\n            # Compare capacity distributions rather than interchangeable ids.\n            n = obs["n_nodes"]\n            actual, pred, stay = [0.0] * n, [0.0] * n, [0.0] * n\n            for u, (typ, v) in enemy_units.items():\n                c = CAP[typ]\n                actual[v] += c\n                pred[self.predicted.get(u, v)] += c\n                stay[self.last_enemy.get(u, v)] += c\n            ep = sum(abs(a - p) for a, p in zip(actual, pred))\n            es = sum(abs(a - s) for a, s in zip(actual, stay))\n            target = 0.90 if ep < es else (0.35 if es < ep else 0.65)\n            self.trust = 0.8 * self.trust + 0.2 * target\n\n        horizon = max(1, min(8, 60 - turn))\n        home = obs["player_base"]\n        plans = {}\n        for uid, (typ, source) in units.items():\n            route = self.home_route(source, SPEED[typ], home, horizon)\n            old = self.plans.get(uid)\n            if (self.bad < 2 and self.last_turn == turn - 1\n                    and old and len(old) > 1 and old[0] == source):\n                route = list(old[1:])[:horizon]\n                route.extend(self.home_route(route[-1], SPEED[typ], home,\n                                             horizon - len(route)))\n            plans[uid] = route\n\n        enemy, predicted = self.predict(obs, plans, horizon)\n        trucks = sorted(u for u in units if units[u][0] == "truck")\n        scooters = sorted(u for u in units if units[u][0] == "scooter")\n        if trucks:\n            k = turn % len(trucks)\n            trucks = trucks[k:] + trucks[:k]\n        if scooters:\n            k = turn % len(scooters)\n            scooters = scooters[k:] + scooters[:k]\n        order = trucks + scooters\n        for sweep in range(3 if self.bad < 2 else 1):\n            sequence = order if sweep % 2 == 0 else list(reversed(order))\n            for uid in sequence:\n                if time.perf_counter() >= deadline:\n                    break\n                plans[uid] = self.improve(\n                    uid, obs, plans, enemy, horizon, deadline)\n            if time.perf_counter() >= deadline:\n                break\n            # Damped best response avoids chasing a wholly different forecast.\n            fresh, predicted = self.predict(obs, plans, horizon)\n            enemy = [[0.45 * a + 0.55 * b for a, b in zip(old, new)]\n                     for old, new in zip(enemy, fresh)]\n\n        moves = {}\n        for uid, (typ, source) in units.items():\n            destination = int(plans[uid][0])\n            if (0 <= destination < obs["n_nodes"]\n                    and self.dist[source][destination] <= SPEED[typ]\n                    and destination != source):\n                moves[str(uid)] = int(destination)\n        self.plans = plans\n        self.last_turn = turn\n        self.last_enemy = {u: data[1] for u, data in enemy_units.items()}\n        self.predicted = predicted\n        return {"moves": moves}\n'
